const fs=require('fs');const puppeteer=require('puppeteer-core');const BASE='https://dev.elmercadodeorigen.com';const wait=ms=>new Promise(r=>setTimeout(r,ms));const R={errors:[],warnings:[],checks:{},runtime:{}};
const ign=req=>{const u=req.url(),e=req.failure()?.errorText||'';return /google-analytics|googletagmanager|doubleclick|clarity|facebook|notification\.mp3|fonts\.googleapis|fonts\.gstatic/i.test(u)||(/ERR_ABORTED/i.test(e)&&/wp-admin\/admin-ajax\.php|wc-ajax=/i.test(u));};
function rt(page,key){const ce=[],rf=[];page.on('console',m=>{if(m.type()==='error'&&!/favicon|third-party cookie|permissions policy/i.test(m.text()))ce.push(m.text())});page.on('requestfailed',q=>{if(!ign(q))rf.push(`${q.url()} :: ${q.failure()?.errorText||'failed'}`)});R.runtime[key]={ce,rf};}
async function vis(el,screen=false){if(!el)return false;return el.evaluate((n,screen)=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);const base=r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'&&+s.opacity>0;return base&&(!screen||(r.right>0&&r.bottom>0&&r.left<innerWidth&&r.top<innerHeight));},screen).catch(()=>false)}
async function first(page,sel,screen=false){for(const e of await page.$$(sel))if(await vis(e,screen))return e;return null}async function click(page,e){if(!e)return false;await e.evaluate(n=>n.scrollIntoView({block:'center'})).catch(()=>{});await wait(150);try{await e.click({delay:20})}catch{await e.evaluate(n=>n.click())}return true}
async function go(page,path,label){const raw=path.startsWith('http')?path:BASE+path,url=raw+(raw.includes('?')?'&':'?')+'qa='+Date.now();const res=await page.goto(url,{waitUntil:'domcontentloaded',timeout:60000});await page.addStyleTag({content:'#cookie-law-info-bar,#cookie-law-info-again,#ht-ctc-chat{display:none!important}'}).catch(()=>{});await wait(900);if(!res||res.status()>=400)R.errors.push(`${label}: HTTP ${res?.status()||'none'}`);if(await page.evaluate(()=>document.documentElement.scrollWidth>document.documentElement.clientWidth+3).catch(()=>false))R.errors.push(`${label}: horizontal overflow`);return res}
async function shot(page,n){await page.screenshot({path:`qa/${n}.png`,fullPage:true})}async function safe(l,f){try{await f()}catch(e){R.errors.push(`${l}: ${e.message}`)}}
async function badge(page){return page.evaluate(()=>{const q='.site-header .shop-cart-count,.site-header .shopping-cart-count,.site-header .cart-count,.site-header .count,.site-header .mini-cart-count,.site-header .elmercado-cart-direct-count';for(const n of document.querySelectorAll(q)){const r=n.getBoundingClientRect(),s=getComputedStyle(n);if(r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'&&+s.opacity>0){const m=(n.textContent||'').match(/\d+/);return{visible:true,value:m?+m[0]:0}}}return{visible:false,value:0}})}
async function chooseVariations(page){const sels=await page.$$('form.variations_form select');if(!sels.length)return{variable:false,enabled:true};const ok=await page.evaluate(()=>{for(const s of document.querySelectorAll('form.variations_form select')){const o=[...s.options].find(x=>x.value&&!x.disabled);if(!o)return false;s.value=o.value;s.dispatchEvent(new Event('input',{bubbles:true}));s.dispatchEvent(new Event('change',{bubbles:true}));if(window.jQuery)window.jQuery(s).trigger('change')}return true});await wait(1600);const enabled=ok&&await page.evaluate(()=>{const b=document.querySelector('.single_add_to_cart_button');return!!b&&!b.disabled&&!b.classList.contains('disabled')});return{variable:true,enabled}}
async function addOne(page,links,mode){for(const href of links){await go(page,href,`product ${mode}`);const v=await chooseVariations(page);if(v.variable)R.checks[`variation-${mode}`]=v;if(v.variable&&!v.enabled)continue;const b=await first(page,'.single_add_to_cart_button:not(.disabled):not([disabled]),form.cart button[type="submit"]:not(.disabled):not([disabled])');if(!b)continue;const nav=page.waitForNavigation({waitUntil:'domcontentloaded',timeout:5000}).catch(()=>null);await click(page,b);await nav;await wait(1300);await go(page,'/carrito/',`cart confirm ${mode}`);if(await page.$('.woocommerce-cart-form .cart_item,.woocommerce-cart-form__cart-item,tr.cart_item'))return true}return false}
async function home(page,mode){await go(page,'/',`home ${mode}`);await shot(page,`v8-home-${mode}`);const b=await badge(page);if(b.visible&&b.value<1)R.errors.push(`home ${mode}: zero badge visible`);const h=await page.evaluate(()=>{const s=document.querySelector('.site-header-inner>.woostify-container'),b=document.querySelector('.site-branding'),t=document.querySelector('.site-tools');if(!s||!b||!t)return null;const a=s.getBoundingClientRect(),x=b.getBoundingClientRect(),y=t.getBoundingClientRect();return[Math.abs(a.top+a.height/2-x.top-x.height/2),Math.abs(a.top+a.height/2-y.top-y.height/2)]});if(!h)R.errors.push(`home ${mode}: header structure missing`);else if(h.some(x=>x>7))R.errors.push(`home ${mode}: header off-center`);if(mode==='mobile'&&await page.$('.emo-featured-products ul.products')){await page.$eval('.emo-featured-products',e=>e.scrollIntoView({block:'center'}));await wait(500);const p=await first(page,'.emo-carousel-control--previous',true),n=await first(page,'.emo-carousel-control--next',true);if(!p||!n)R.errors.push('home mobile: carousel arrows missing');if(n){const a=await page.$eval('.emo-featured-products ul.products',e=>e.scrollLeft);await click(page,n);await wait(600);const z=await page.$eval('.emo-featured-products ul.products',e=>e.scrollLeft);if(z<=a+2)R.errors.push('home mobile: carousel arrow does not move')}}await page.evaluate(()=>scrollTo(0,0));await page.keyboard.press('Tab');await page.keyboard.press('Tab');if(!(await page.evaluate(()=>document.activeElement&&document.activeElement!==document.body)))R.errors.push(`home ${mode}: keyboard focus missing`)}
async function mobileMenu(page){await go(page,'/','mobile menu');const t=await first(page,'.site-header .toggle-sidebar-menu-btn',true);if(!t)return R.errors.push('mobile menu: toggle missing');await click(page,t);await wait(450);if(!(await page.evaluate(()=>document.documentElement.classList.contains('sidebar-menu-open'))))R.errors.push('mobile menu: did not open');await shot(page,'v8-mobile-menu-open');const c=await first(page,'.sidebar-menu .elmercado-mobile-menu-close,.sidebar-menu .close-sidebar-menu-btn,.sidebar-menu .close-sidebar-menu,.sidebar-menu [class*="close-sidebar"]');if(!c)R.errors.push('mobile menu: close control missing');else{await click(page,c);await wait(1000);if(await page.evaluate(()=>document.documentElement.classList.contains('sidebar-menu-open')))R.errors.push('mobile menu: close control did not close')}await click(page,t);await wait(350);await page.keyboard.press('Escape');await wait(500);if(await page.evaluate(()=>document.documentElement.classList.contains('sidebar-menu-open')))R.errors.push('mobile menu: Escape did not close')}
async function search(page,mode){await go(page,'/',`search ${mode}`);const t=await first(page,'.site-header .header-search-icon,.site-header .search-icon,.site-header .site-search-toggle,.site-header .js-dgwt-wcas-search-icon-handler',true);if(!t)return R.errors.push(`search ${mode}: toggle missing`);await click(page,t);await wait(600);const i=await first(page,'input[type="search"]',true);if(!i)R.errors.push(`search ${mode}: input missing`);else await i.type('aceite');await go(page,'/?s=aceite&post_type=product',`search result ${mode}`);if(!(await page.evaluate(()=>document.querySelectorAll('li.product').length>0)))R.errors.push(`search ${mode}: known query empty`);await go(page,'/?s=zzzz-no-existe-qa-987654&post_type=product',`search no result ${mode}`);if(await page.evaluate(()=>document.querySelectorAll('li.product').length>0))R.errors.push(`search ${mode}: impossible query has products`)}
async function shop(page,mode){await go(page,'/tienda/',`shop ${mode}`);await shot(page,`v8-shop-${mode}`);const seller=await page.evaluate(()=>[...document.querySelectorAll('select')].some(s=>[...s.options].some(o=>/(todos los productores|todos los vendedores)/i.test(o.textContent||''))&&(()=>{const r=s.getBoundingClientRect(),c=getComputedStyle(s);return r.width>0&&r.height>0&&c.display!=='none'&&c.visibility!=='hidden'})()));if(seller)R.errors.push(`shop ${mode}: producer filter visible`);const ord=await page.$('.woocommerce-ordering select');if(!ord)R.errors.push(`shop ${mode}: ordering missing`);else if((await ord.evaluate(e=>[getComputedStyle(e).borderTopWidth,getComputedStyle(e).borderBottomWidth])).includes('0px'))R.errors.push(`shop ${mode}: ordering border incomplete`);const txt=await page.$eval('.woocommerce-result-count',e=>(e.textContent||'').replace(/\s+/g,' ').trim()).catch(()=>'');if(/mostrando/i.test(txt)&&!/\d\s*de\s*\d/i.test(txt))R.errors.push(`shop ${mode}: result count malformed`);const titles=await page.$$eval('ul.products li.product .woocommerce-loop-product__title,ul.products li.product .elmercado-product-title-link',a=>a.slice(0,10).map(e=>{const s=getComputedStyle(e);return[e.getBoundingClientRect().height,parseFloat(s.lineHeight),String(s.webkitLineClamp||s.lineClamp||'')]}));if(!titles.length)R.errors.push(`shop ${mode}: titles missing`);else if(titles.some(([h,l,c])=>l&&h+1<l*1.9&&c!=='2'))R.errors.push(`shop ${mode}: two-line titles broken`);if(mode==='desktop'&&!await page.$('.widget-area .widget'))R.errors.push('shop desktop: filter sections missing');if(!await page.$('.widget_price_filter .price_slider,.price_slider_wrapper .ui-slider-horizontal'))R.warnings.push(`shop ${mode}: price slider not detected`);const cat=await page.$('.widget_product_categories a,.product-categories a');if(cat){const u=await cat.evaluate(a=>a.href);await go(page,u,`category ${mode}`)}else R.warnings.push(`shop ${mode}: category link not detected`);await go(page,'/tienda/',`shop restore ${mode}`);const pg=await page.$('.woocommerce-pagination a.page-numbers');if(pg){const u=await pg.evaluate(a=>a.href);await go(page,u,`pagination ${mode}`)}else R.warnings.push(`shop ${mode}: pagination absent`);await go(page,'/tienda/',`shop links ${mode}`);return page.$$eval('li.product a.woocommerce-loop-product__link',a=>[...new Set(a.map(x=>x.href))].slice(0,12)).catch(()=>[])}
async function commerce(page,mode,links){if(!await addOne(page,links,mode))return R.errors.push(`cart ${mode}: unable to add available product`);await shot(page,`v8-cart-${mode}`);const b=await badge(page);if(!b.visible||b.value<1)R.errors.push(`cart ${mode}: positive badge missing`);const q=await page.$('.woocommerce-cart-form input.qty');if(!q)R.errors.push(`cart ${mode}: quantity missing`);else{await q.click({clickCount:3});await q.type('2');const u=await first(page,'button[name="update_cart"],input[name="update_cart"]');if(u){await click(page,u);await wait(1200)}}const cp=await page.$('input#coupon_code,input[name="coupon_code"]');if(cp){await cp.type('QA-CUPON-INVALIDO-987654');const ap=await first(page,'button[name="apply_coupon"],input[name="apply_coupon"]');if(ap){await click(page,ap);await wait(1200);if(!await page.$('.woocommerce-error,.woocommerce-notice--error,[role="alert"]'))R.errors.push(`cart ${mode}: invalid coupon error missing`)}}await go(page,'/finalizar-compra/',`checkout ${mode}`);await shot(page,`v8-checkout-${mode}`);if(!await page.$('form.checkout,#customer_details,.woocommerce-checkout'))R.errors.push(`checkout ${mode}: form missing`)}
async function content(page,mode){await go(page,'/contacto/',`contact ${mode}`);const f=await page.$('form.wpcf7-form,.elementor-form,form[id*="contact"]');if(!f)R.errors.push(`contact ${mode}: form missing`);else{const sub=await first(page,'form.wpcf7-form input[type="submit"],form.wpcf7-form button[type="submit"],.elementor-form button[type="submit"],form[id*="contact"] button[type="submit"]');if(sub){await click(page,sub);await wait(600);const bad=await f.evaluate(x=>!x.checkValidity()).catch(()=>false),msg=await page.$('.wpcf7-not-valid-tip,.elementor-message-danger,[aria-invalid="true"]');if(!bad&&!msg)R.warnings.push(`contact ${mode}: validation message not detected`)}}await go(page,'/blog/',`blog ${mode}`);const a=await page.$eval('article a[href],h2 a[href]',x=>x.href).catch(()=>null);if(a)await go(page,a,`blog article ${mode}`);else R.warnings.push(`blog ${mode}: article absent`);await go(page,'/',`footer ${mode}`);const legal=await page.evaluate(()=>[...document.querySelectorAll('footer a[href],.site-footer a[href]')].filter(a=>/privacidad|cookies|aviso legal|t[eé]rminos|condiciones/i.test((a.textContent||'')+' '+a.href)).map(a=>a.href).filter((v,i,a)=>a.indexOf(v)===i).slice(0,6));if(!legal.length)R.errors.push(`footer ${mode}: legal links missing`);for(let i=0;i<legal.length;i++)await go(page,legal[i],`legal ${mode} ${i}`);await go(page,'/tienda/hidalgo-de-la-jara/',`vendor ${mode}`);await shot(page,`v8-vendor-${mode}`);if(!(await page.evaluate(()=>document.querySelectorAll('li.product').length>0)))R.errors.push(`vendor ${mode}: products missing`);const gap=await page.evaluate(()=>{const t=document.querySelector('.wcfmmp-store-tabs,.wcfm_store_tabs,.store-tabs,.wcfmmp-store-tab');return t&&t.nextElementSibling?t.nextElementSibling.getBoundingClientRect().top-t.getBoundingClientRect().bottom:null});if(gap!==null&&gap<16)R.errors.push(`vendor ${mode}: tabs gap ${Math.round(gap)}px`)}
async function mode(browser,modeName,vp){const ctx=await browser.createBrowserContext(),p=await ctx.newPage();await p.setViewport(vp);p.setDefaultNavigationTimeout(60000);rt(p,modeName);await safe(`home ${modeName}`,()=>home(p,modeName));if(modeName==='mobile')await safe('mobile menu',()=>mobileMenu(p));await safe(`search ${modeName}`,()=>search(p,modeName));let links=[];await safe(`shop ${modeName}`,async()=>{links=await shop(p,modeName)});await safe(`commerce ${modeName}`,()=>commerce(p,modeName,links));await safe(`content ${modeName}`,()=>content(p,modeName));const x=R.runtime[modeName],ce=[...new Set(x.ce)],rf=[...new Set(x.rf)];if(ce.length)R.errors.push(`${modeName}: console errors: ${ce.slice(0,3).join(' | ')}`);if(rf.length)R.errors.push(`${modeName}: request failures: ${rf.slice(0,3).join(' | ')}`);await ctx.close()}
(async()=>{fs.mkdirSync('qa',{recursive:true});const b=await puppeteer.launch({executablePath:'/usr/bin/google-chrome',headless:'new',protocolTimeout:120000,args:['--no-sandbox','--disable-dev-shm-usage']});try{const c=await b.createBrowserContext(),p=await c.newPage();await p.setViewport({width:1440,height:1000});rt(p,'clean');await go(p,'/carrito/','empty cart');if(!await p.evaluate(()=>/carrito.*vac[ií]o|tu carrito est[aá] vac[ií]o|volver a la tienda|return to shop/i.test(document.body.innerText)))R.errors.push('empty cart state missing');const z=await badge(p);if(z.visible&&z.value<1)R.errors.push('empty cart: zero badge visible');await go(p,'/mi-cuenta/','account logged out');if(!await p.$('form.woocommerce-form-login,input[name="username"],input[name="password"]'))R.warnings.push('account logged-out form not detected');const x=R.runtime.clean;if([...new Set(x.ce)].length)R.errors.push('clean: console error(s)');if([...new Set(x.rf)].length)R.errors.push('clean: request failure(s)');await c.close();await mode(b,'desktop',{width:1440,height:1000});await mode(b,'mobile',{width:390,height:844,isMobile:true,hasTouch:true,deviceScaleFactor:1})}finally{await b.close()}R.errors=[...new Set(R.errors)];R.warnings=[...new Set(R.warnings)];fs.writeFileSync('qa/report-v8.json',JSON.stringify(R,null,2));if(R.errors.length){console.error(R.errors.join('\n'));process.exitCode=2}else console.log(`AUDIT_OK warnings=${R.warnings.length}`)})();